mapper.select:
SELECT m.module_id, m.tenant_id, m.module_code, m.module_nm, m.icon_nm, m.module_url, m.sort_order, m.use_at, m.created_at, m.updated_at, ( SELECT COUNT(*) FROM tb_menu mn WHERE mn.module_id = m.module_id ) AS menu_count FROM tb_module m WHERE m.tenant_id = #{tenantId}
AND m.use_at = #{useAt}
ORDER BY m.sort_order ASC, m.module_id ASC

SELECT module_id
FROM tb_module
WHERE tenant_id = #{tenantId}
  AND module_code = #{moduleCode}

mapper.delete:
DELETE FROM tb_module
WHERE module_id = #{moduleId}
  AND tenant_id = #{tenantId}

mapper.select:
SELECT COUNT(*)
FROM tb_menu
WHERE module_id = #{moduleId}
  AND tenant_id = #{tenantId}
